import java.sql.*;
public class JdbcStudentRepositoryDemo { public static void main(String[] args){String url=System.getProperty("school.db.url");if(url==null||url.trim().isEmpty()){System.out.println("JDBC stage: set -Dschool.db.url=jdbc:... and provide a matching JDBC driver.");System.out.println("Example SQL is in FinalIntegratedProject/sql/schema.sql");return;}try(Connection c=DriverManager.getConnection(url,System.getProperty("school.db.user",""),System.getProperty("school.db.password",""));PreparedStatement p=c.prepareStatement("SELECT student_id, first_name, last_name FROM students");ResultSet rs=p.executeQuery()){while(rs.next())System.out.println(rs.getString(1)+" - "+rs.getString(2)+" "+rs.getString(3));}catch(SQLException e){System.out.println("Database connection/query failed: "+e.getMessage());}} }
